-- Icecrown Citadel: SmartAI for 18 trash and gunship creature types that had none
-- Ported from TrinityCore 3.3.5. TrinityCore's 10 and 25 player difficulty bits are moved to this core's difficulty bits.

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (10404,36880,36998,37003,37004,37017,37022,37023,37026,37032,37033,37035,37148,37544,37546,37662,37665,37702) AND `AIName` = '' AND `ScriptName` = '';

DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (10404,36880,36998,37003,37004,37017,37022,37023,37026,37032,37033,37035,37148,37544,37546,37662,37665,37702);
